// Edit these values for each manual run.
const config = {
  source_url: 'https://www.youtube.com/watch?v=MQHIukVzupE',
  source_title: 'LUCAS PAVANATO FALA SOBRE SUAS EXPECTATIVAS PARA INÍCIO DO MANDATO COMO DEPUTADO FEDERAL',
  source_channel: 'Itatiaia',
  pilot: true,
  force_reprocess: false,
  // Set to reuse an existing Vizard project instead of creating (and paying for) a new one.
  vizard_project_id: '35073699',
};

const m = config.source_url.match(/(?:v=|youtu\.be\/|shorts\/|live\/)([A-Za-z0-9_-]{11})/);
if (!m) throw new Error('CONFIG_INVALID: could not extract YouTube video id from source_url');

return [{ json: { ...config, source_video_id: m[1], started_at: new Date().toISOString() } }];

const res = $input.first().json;
const config = $('CONFIG').first().json;

const messages = {
  4001: 'Invalid API key', 4002: 'Project creation failed', 4003: 'Rate limit exceeded',
  4004: 'Unsupported video format', 4005: 'Video file is broken', 4006: 'Illegal parameter',
  4007: 'Insufficient remaining minutes', 4008: 'Cannot download video from URL',
  4009: 'Invalid video URL', 4010: 'Cannot detect spoken language',
};

if (res?.code !== 2000 || !res?.projectId) {
  const detail = messages[res?.code] ?? 'unexpected response';
  throw new Error(`VIZARD_CREATE_FAILED: code=${res?.code} ${detail} ${res?.errMsg ?? ''}`.trim());
}

return [{ json: { ...config, vizard_project_id: String(res.projectId), vizard_share_link: res.shareLink ?? null } }];

const MAX_POLLS = 40;
const res = $input.first().json;
const ctx = $('WAIT').first().json;
const poll = $runIndex + 1;

if (res?.code === 1000) {
  if (poll >= MAX_POLLS) throw new Error(`VIZARD_TIMEOUT: project ${ctx.vizard_project_id} still processing after ${poll} polls`);
  return [{ json: { ...ctx, vizard_status: 'PROCESSING', polls: poll } }];
}
if (res?.code === 2000) {
  if (!Array.isArray(res.videos)) throw new Error('VIZARD_INVALID_RESPONSE: code 2000 without videos array');
  return [{ json: { ...ctx, vizard_status: 'COMPLETE', polls: poll, vizard: res } }];
}
throw new Error(`VIZARD_QUERY_FAILED: code=${res?.code} ${res?.errMsg ?? ''}`.trim());

const ctx = $input.first().json;
const videos = ctx.vizard.videos;

const parseTopics = (v) => {
  if (Array.isArray(v)) return v;
  try { const p = JSON.parse(v ?? '[]'); return Array.isArray(p) ? p : []; } catch { return []; }
};

const clips = videos
  .filter((v) => v && v.videoId && v.videoUrl)
  .map((v) => ({
    clip_id: String(v.videoId),
    video_url: v.videoUrl,
    duration: Math.round((Number(v.videoMsDuration) || 0) / 1000),
    title: v.title ?? '',
    transcript: v.transcript ?? '',
    viral_score: Number(v.viralScore) || 0,
    viral_reason: v.viralReason ?? '',
    related_topic: parseTopics(v.relatedTopic).join(', '),
    clip_editor_url: v.clipEditorUrl ?? null,
    source_url: ctx.source_url,
    source_video_id: ctx.source_video_id,
    source_title: ctx.source_title,
    source_channel: ctx.source_channel,
    vizard_project_id: ctx.vizard_project_id,
  }));

if (clips.length === 0) throw new Error(`NO_CLIPS_RETURNED: project ${ctx.vizard_project_id} returned ${videos.length} videos, none usable`);

const withTranscript = clips.filter((c) => c.transcript.trim().length > 0).length;
console.log(`clips=${clips.length} with_transcript=${withTranscript} polls=${ctx.polls}`);

return clips.map((c) => ({ json: c }));
